import{_ as d,o as a,c as e,a4 as r}from"./chunks/framework.B8PHay3u.js";const f=JSON.parse('{"title":"功能总览","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1789295182000}'),l={name:"features.md"};function o(i,t,c,h,n,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="功能总览" tabindex="-1">功能总览 <a class="header-anchor" href="#功能总览" aria-label="Permalink to &quot;功能总览&quot;">​</a></h1><p>服务对象：华星镍业检修维护部电气自动化车间。<strong>不涉及物资价格和成本核算。</strong></p><h2 id="功能清单" tabindex="-1">功能清单 <a class="header-anchor" href="#功能清单" aria-label="Permalink to &quot;功能清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>库存模块</td><td>库存管理</td><td>二级库物资与库存余额、入出库流水；流水可修正、冲销并自动重算后续余额。</td></tr><tr><td>库存模块</td><td>补库与低库存</td><td>按近 6 个月出库计算建议数量，低库存工作台一键发起补库。</td></tr><tr><td>库存模块</td><td>精简库存</td><td>精简/完整模式开关；精简库存独立表、小程序只读、后台单页导入查询。</td></tr><tr><td>申购模块</td><td>申购计划</td><td>可暂缺物料编码，到货时关联或新建二级库物资；支持周期性计划模板。</td></tr><tr><td>申购模块</td><td>请购与到货</td><td>按申购单号管理，状态取自外部平台并只进不退：已申购 → 已采购 → 部分入库 → 已入库。</td></tr><tr><td>采购跟踪</td><td>采购跟踪</td><td>按申购单号整单同步外部平台（采购人、合同号、合同签订日期、船名、状态），只补空值。</td></tr><tr><td>数据协同</td><td>Excel 导入导出</td><td>布局模板随代码版本管理；导入导出走异步任务并提供进度查询。</td></tr><tr><td>数据协同</td><td>链接分享</td><td>生成带失效时间的匿名分享页，可配置公开页展示列。</td></tr><tr><td>平台能力</td><td>图片附件</td><td>上传与缩略图预览，按 <code>file_id</code> 读取，支持 CDN/图床加速，含悬空文件清理。</td></tr><tr><td>平台能力</td><td>AI 搜索与 MCP</td><td>AI 搜索配置（API Key 加密入库）与 MCP 工具，供 AI Agent 按角色权限调用接口。</td></tr><tr><td>平台能力</td><td>备忘录</td><td>多标签纯文本备忘录，字号可调并记录在浏览器本地。</td></tr><tr><td>用户与权限</td><td>管理后台用户</td><td>四种角色、微信身份按 AppID 记录并支持人工合并，接口令牌加密入库并回显。</td></tr></tbody></table><h2 id="角色能力" tabindex="-1">角色能力 <a class="header-anchor" href="#角色能力" aria-label="Permalink to &quot;角色能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>可写</th><th>只读</th></tr></thead><tbody><tr><td>系统管理员 <code>SUPER_ADMIN</code></td><td>全部模块 + 用户与系统设置</td><td>全部</td></tr><tr><td>仓库管理员 <code>WAREHOUSE_ADMIN</code></td><td>二级库物资、库存策略、入出库、流水</td><td>申购模块、采购跟踪</td></tr><tr><td>申购管理员 <code>PURCHASE_ADMIN</code></td><td>申购计划、申购记录、物料编码库</td><td>库存模块</td></tr><tr><td>只读 <code>READ_ONLY</code></td><td>—</td><td>全部业务数据</td></tr></tbody></table><p>逐接口的权限依赖见<a href="/Electrical-Manager/dev-overview">系统概述</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>每项功能对应的接口：<a href="/Electrical-Manager/api">接口文档与 Mock</a></li><li>每项功能对应的表结构与流程：<a href="/Electrical-Manager/dev-data-model">数据模型</a>、<a href="/Electrical-Manager/dev-flows">核心数据流</a></li><li>手工验收清单：<a href="/Electrical-Manager/manual-functional-test-plan">人工功能测试方案</a></li></ul>',9)])])}const u=d(l,[["render",o]]);export{f as __pageData,u as default};
